public class Main {
    public static void main(String[] args) {
        int[][] data = {
            {1, 2},
            null,
            {3},
            {4, 5, 6}
        };
        int total = 0;
        for (int[] row : data) {
            if (row == null) continue;
            for (int v : row) {
                if (v == 5) break;
                total += v;
            }
        }
        System.out.print(total);
    }
}

public class Main {
    public static void main(String[] args) {
        int count = 0;
        outer:
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 4; j++) {
                if (j == 2) {
                    continue outer;
                }
                count += i + j;
                System.out.print(i + "" + j + " ");
            }
        }
        System.out.print("|" + count);
    }
}

public class Main {
    public static void main(String[] args) {
        int x = 0;
        int total = 0;
        do {
            total += ++x;
            if (x == 2) {
                continue;
            }
            total += 10;
        } while (x < 3);
        System.out.print(x + ":" + total);
    }
}

public class Main {
    static int score(int n) {
        return switch (n) {
            case 1, 2 -> n * 10;
            case 3 -> {
                int x = n + 4;
                yield x * 2;
            }
            default -> 0;
        };
    }
    public static void main(String[] args) {
        var a = score(2);
        var b = score(3);
        System.out.print(a + ":" + b);
    }
}

public class Main {
    static void print(int n) {
        switch (n) {
            case 1:
                System.out.print("A");
            case 2:
                System.out.print("B");
                break;
            default:
                System.out.print("D");
        }
    }
    public static void main(String[] args) {
        print(1);
        System.out.print(":");
        print(3);
    }
}

